const toast=document.getElementById('toast');function note(t){toast.textContent=t;toast.style.display='block';setTimeout(()=>toast.style.display='none',2400)}async function shareSite(){if(navigator.share){try{return await navigator.share({title:'FlexLog Transportes',url:location.href})}catch(e){}}try{await navigator.clipboard.writeText(location.href);note('Link copiado.')}catch(e){note(location.href)}}document.getElementById('share').onclick=shareSite;document.getElementById('share2').onclick=shareSite;document.getElementById('wish').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent.startsWith('♡')?'✓ Na lista de desejos':'♡ Lista de desejos'};const dlg=document.getElementById('light'),big=document.getElementById('big');document.querySelectorAll('.shot img').forEach(i=>i.parentElement.onclick=()=>{big.src=i.src;big.alt=i.alt;dlg.showModal()});document.getElementById('close').onclick=()=>dlg.close();dlg.onclick=e=>{if(e.target===dlg)dlg.close()};fetch('/flexlog.apk',{method:'HEAD',cache:'no-store'}).then(r=>{if(r.ok){const b=document.getElementById('installBtn');b.href='/flexlog.apk';b.textContent='Baixar';b.classList.remove('disabled');b.removeAttribute('aria-disabled')}}).catch(()=>{});